using System;using MySimulator.Rebuild;
static class Probe{public static void Run(int t){var c=new Circuit(t);Console.WriteLine($"track {t} length={c.length:0} width={c.width:0.0} points={c.points.Length}");for(int i=0;i<20;i++){float p=i/20f;float v=Vehicle.SpeedAhead(c,p,7.9f,7f);float h0=c.Heading(p),h1=c.Heading(p+16f/c.length);Console.WriteLine($"p={p:0.00} speedAhead={v:0.0} dHeading16m={MathUtil.Wrap(h1-h0)*57.3f:0.0}deg");}}}
static class StartPts{public static void Run(){for(int t=0;t<SourceRoutes.Names.Length;t++){var c=new Circuit(t);var p=c.Lane(0.988f,0f);Console.WriteLine($"{t}\t{p.x}\t{p.z}");}}}
static class Widths{public static void Run(){for(int t=0;t<SourceRoutes.Names.Length;t++){var c=new Circuit(t);Console.WriteLine($"{t}\t{SourceRoutes.Names[t]}\tlen={c.length:0}\twidth={c.width:0.0}");}}}
static class StepTest{public static void Run(int car,float steerIn,float thr){var r=new Race(0,1,0f);var v=r.Add("H",true,Compound.Medium);v.carModel=car;r.countdown=0;r.started=true;v.Place(r.track,0.988f,0f);
 float dt=1f/120f;float t=0;int n=0;Console.WriteLine($"car {car} steer={steerIn} throttle={thr}");
 for(int i=0;i<120*20;i++){float steer=i<120*3?0:steerIn;float throttle=v.speed<25?1f:thr;v.input=new DriverInput(throttle,0,steer);r.Step(dt);t+=dt;if(i%120==0)Console.WriteLine($"t={t:0.0} speed={v.speed:0.0} yaw={v.yawRate:0.000} steerAng={v.steering:0.000} head={v.heading:0.000} lat={v.lateral:0.0}");}}}
static class GateProbe{public static void Run(int t,int c){var r=new Race(t,1,0f);var v=r.Add("A",false,Compound.Medium);v.carModel=c;r.countdown=0;r.started=true;v.Place(r.track,0.988f,0f);float dt=1f/120f;float prev=v.progress;int an=0;
 for(int i=0;i<120*130;i++){r.Step(dt);float d=v.progress-prev;if(d<-0.5f)d+=1;if(d>0.5f)d-=1;if(Math.Abs(d)>0.004f||d<-0.0001f){if(an++<12)Console.WriteLine($"t={i*dt:0.00} prog {prev:0.0000}->{v.progress:0.0000} d={d:0.0000} speed={v.speed:0.0} lat={v.lateral:0.0} gate={v.nextGate}");}if(prev<0.25f&&v.progress>=0.25f)Console.WriteLine($"CROSS .25 at t={i*dt:0.00} gate={v.nextGate} lat={v.lateral:0.0} offTrack={v.offTrackTime:0.00} finished={v.finished} retired={v.retired} onSurface={v.onDrivingSurface} ext={v.externalPhysics}");prev=v.progress;}
 Console.WriteLine($"anomalies={an} final gate={v.nextGate} laps={v.completedLaps}");}}
static class Trace{public static void Run(int t,int c,float t0,float t1){var r=new Race(t,1,0f);var v=r.Add("A",false,Compound.Medium);v.carModel=c;r.countdown=0;r.started=true;v.Place(r.track,0.988f,0f);float dt=1f/120f;
 for(int i=0;i<120*(int)t1;i++){r.Step(dt);float tm=i*dt;if(tm>=t0&&i%30==0)Console.WriteLine($"t={tm:0.00} prog={v.progress:0.0000} speed={v.speed:0.0} lat={v.lateral:0.0} yaw={v.yawRate:0.00} steer={v.steering:0.00} thr={v.input.throttle:0.0} brk={v.input.brake:0.0} des={v.dbgA:0.0} curv={v.dbgB:0.000} lx={v.dbgC:0.0} head={v.heading:0.00}");}}}
static class CoreProbe{public static void Run(float dt){foreach(int variant in new[]{0,1,2}){var r=new Race(variant,2,0);r.countdown=0;var v=r.Add("Autopilot",false,Compound.Medium);float worst=0;bool inv=false;int trans=0;
 for(int i=0;i<40000&&!v.finished;i++){if(dt>=0.0199f)r.Step(dt);else r.Advance(dt);worst=Math.Max(worst,Math.Abs(v.lateral));if(v.lapInvalid!=inv){inv=v.lapInvalid;if(trans++<6)Console.WriteLine($"  v{variant} t={i*dt:0.0} lapInvalid->{inv} lat={v.lateral:0.0} prog={v.progress:0.000} speed={v.speed:0.0} laps={v.completedLaps}");}}
 Console.WriteLine($"variant {variant} dt={dt}: finished={v.finished} laps={v.completedLaps} best={v.bestLap:0.0} last={v.lastLap:0.0} finish={v.finishTime:0.0} worstLat={worst:0.0}");}}}
static class CornerProbe{public static void Run(int t,float p0,float p1){var c=new Circuit(t);for(float p=p0;p<=p1;p+=0.003f){float step=16f/c.length;float h0=c.Heading(p),h1=c.Heading(p+step),h2=c.Heading(p+2*step);Console.WriteLine($"p={p:0.000} d1={MathUtil.Wrap(h1-h0)*57.3f:0.0}deg d2={MathUtil.Wrap(h2-h1)*57.3f:0.0}deg speedAhead={Vehicle.SpeedAhead(c,p,7.9f,5f):0.0}");}}}
static class PitProbe{public static void Run(int t,int c){var r=new Race(t,3,0f);var v=r.Add("A",false,Compound.Medium);v.carModel=c;r.countdown=0;r.started=true;v.Place(r.track,0.988f,0f);v.pitRequested=true;float dt=1f/120f;bool wasActive=false,wasServ=false;float maxSpeedInLane=0;int hits=0;
 for(int i=0;i<120*400;i++){r.Step(dt);if(v.pitActive&&!wasActive){Console.WriteLine($"t={i*dt:0.0} ENTER pit lane at speed {v.speed:0.0} m/s ({v.speed*3.6f:0} km/h)");}if(v.pitActive)maxSpeedInLane=Math.Max(maxSpeedInLane,v.speed);if(v.servicing&&!wasServ)Console.WriteLine($"t={i*dt:0.0} SERVICE start, speed {v.speed:0.0}, box dist {(v.position-r.track.PitBox).Magnitude:0.00} m");if(!v.servicing&&wasServ)Console.WriteLine($"t={i*dt:0.0} RELEASED, wear {v.Wear:0.00}");wasActive=v.pitActive;wasServ=v.servicing;if(v.finished)break;}
 Console.WriteLine($"max speed in lane {maxSpeedInLane:0.0} m/s ({maxSpeedInLane*3.6f:0} km/h), limit {Vehicle.PitSpeedLimit:0.0} m/s, penalty {v.penalty:0.0}, finished={v.finished}");}}
static class PitDist{public static void Run(){for(int t=0;t<60;t++){var c=new Circuit(t);float lat;float p=c.Find(c.PitRoute[0],out lat);float last;float p2=c.Find(c.PitRoute[c.PitRoute.Length-1],out last);Console.WriteLine($"{t}\tentryLat={lat:0.0}\texitLat={last:0.0}\tentryP={p:0.000}\texitP={p2:0.000}\tbox={c.PitServiceIndex}/{c.PitRoute.Length}");}}}
